describe('Error Message Accessibility for Screen Readers', () => {
  beforeEach(() => {
    cy.visit('/error-page');
  });

  it('should display error message with proper ARIA attributes for screen reader accessibility', () => {
    // Intercept the API call that triggers the error
    cy.intercept('POST', '/api/validate-form').as('validateForm');
    cy.get('[data-testid="submit-button"]').click();

    // Trigger the error state
    cy.wait('@validateForm').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message is visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify error message has correct ARIA attributes
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-atomic', 'true');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-describedby', 'error-details');

    // Verify error message contains descriptive text
    cy.get('[data-testid="error-message"]').should('contain', 'Validation failed');

    // Verify error details are accessible
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Field X is required');

    // Verify screen reader announces error message
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="error-message"]').should('be.announced');
  });

  it('should handle multiple error messages without overlapping screen reader content', () => {
    // Intercept the API call that triggers multiple errors
    cy.intercept('POST', '/api/validate-form').as('validateForm');
    cy.get('[data-testid="submit-button"]').click();

    // Trigger the error state with multiple validation errors
    cy.wait('@validateForm').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify multiple error messages are displayed
    cy.get('[data-testid="error-message-1"]').should('be.visible');
    cy.get('[data-testid="error-message-2"]').should('be.visible');

    // Verify error messages do not overlap and are announced in sequence
    cy.get('[data-testid="error-message-1"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="error-message-2"]').should('have.attr', 'aria-live', 'polite');

    // Verify error messages are announced in a logical order
    cy.get('[data-testid="error-message-1"]').should('be.announced');
    cy.get('[data-testid="error-message-2"]').should('be.announced');

    // Verify error details are accessible and announced separately
    cy.get('[data-testid="error-details-1"]').should('be.visible');
    cy.get('[data-testid="error-details-2"]').should('be.visible');

    // Verify error messages are not announced again after first announcement
    cy.get('[data-testid="error-message-1"]').should('not.be.announced');
  });
});
